# Evaluating Agentic Workflows: one golden eval case.
case = {
    "must_include": ["30 days", "invoice id"],
    "must_not_include": ["guaranteed approval"],
}
answer = "Refund requests need an invoice id and must arrive within 30 days."

def passes(case, answer):
    lower = answer.lower()
    return all(x.lower() in lower for x in case["must_include"]) and all(x.lower() not in lower for x in case["must_not_include"])

print("pass" if passes(case, answer) else "fail")
